<body>
<div id="wrap">
  <canvas id="scene"></canvas>
  <div id="hud">
    <div class="title">Gouraud-shaded cube &middot; Canvas 2D</div>
    <div>FPS: <span id="fps">--</span></div>
    <div>State: <span id="state">running</span></div>
    <div>Render: <span id="mode">shaded</span></div>
    <div class="dim">&nbsp;</div>
    <div><span class="key">W</span> wireframe toggle</div>
    <div><span class="key">P</span> pause / resume</div>
  </div>
